  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'علاقة جملة (قد حدث ما خاف منه) بما قبلها:', '["استدراك", "نتيجة", "سبب", "تتمة لها"]'::jsonb, 1, 'فشل العمليات الاثنتي عشرة انتهى إلى وقوع ما كان يخافه؛ فالجملة نتيجة لما قبلها.', NULL, 'ad270826-2026-4c00-9d00-270820260001', 'e1a82701-2026-4c00-9d00-000000000001', 'كان الدكتور سميث مؤمنًا بأن البصر نعمة كبيرة، ويتمنى ألا يفقد بصره وكان يكرر هذه الجملة دائمًا. لكن حينما تجاوز الستين من عمره بدأ بصره يضعف وشعر بالغبش على عينيه وأصبحت عيناه لا يمكنهما التفريق بين بعض الأشياء، فذهب إلى الطبيب وكانت الفاجعة؛ حيث اكتشف الطبيب أنه قد فقد إحدى عينيه وأن بصره يضعف مع الوقت وأنه سيصاب بالعمى في العين الثانية. قام بإجراء ١٢ عملية جراحية على أمل أن يعود له بصره لكن لم يحدث، وقد حدث ما خاف منه حيث فقد العين الثانية. تعايش سميث مع فقدان بصره وتيقن أن العقل هو أهم شيء حتى لو فقد جميع حواسه.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'ماذا يستفاد من النص؟', '["التأقلم مع كل الظروف", "الحرص على العلاج المبكر", "تجنب إجراء العمليات", "الخوف من المستقبل"]'::jsonb, 0, 'خاتمة النص أن سميث تعايش مع فقد بصره وأدرك قيمة عقله؛ فالعبرة هي التأقلم مع الظروف مهما اشتدت.', NULL, 'ad270826-2026-4c00-9d00-270820260001', 'e1a82701-2026-4c00-9d00-000000000001', 'كان الدكتور سميث مؤمنًا بأن البصر نعمة كبيرة، ويتمنى ألا يفقد بصره وكان يكرر هذه الجملة دائمًا. لكن حينما تجاوز الستين من عمره بدأ بصره يضعف وشعر بالغبش على عينيه وأصبحت عيناه لا يمكنهما التفريق بين بعض الأشياء، فذهب إلى الطبيب وكانت الفاجعة؛ حيث اكتشف الطبيب أنه قد فقد إحدى عينيه وأن بصره يضعف مع الوقت وأنه سيصاب بالعمى في العين الثانية. قام بإجراء ١٢ عملية جراحية على أمل أن يعود له بصره لكن لم يحدث، وقد حدث ما خاف منه حيث فقد العين الثانية. تعايش سميث مع فقدان بصره وتيقن أن العقل هو أهم شيء حتى لو فقد جميع حواسه.', 2, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
