  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'وفقًا للنص، كيف يُصبَر على البلاء؟', '["الاحتساب", "الشكوى", "التجاهل", "الانعزال"]'::jsonb, 0, 'تعايش سميث مع الفقد راضيًا متيقنًا بما بقي له من نعم، وهذا هو الصبر بالاحتساب.', NULL, 'ad270826-2026-4c00-9d00-270820260001', 'e1a82701-2026-4c00-9d00-000000000001', 'كان الدكتور سميث مؤمنًا بأن البصر نعمة كبيرة، ويتمنى ألا يفقد بصره وكان يكرر هذه الجملة دائمًا. لكن حينما تجاوز الستين من عمره بدأ بصره يضعف وشعر بالغبش على عينيه وأصبحت عيناه لا يمكنهما التفريق بين بعض الأشياء، فذهب إلى الطبيب وكانت الفاجعة؛ حيث اكتشف الطبيب أنه قد فقد إحدى عينيه وأن بصره يضعف مع الوقت وأنه سيصاب بالعمى في العين الثانية. قام بإجراء ١٢ عملية جراحية على أمل أن يعود له بصره لكن لم يحدث، وقد حدث ما خاف منه حيث فقد العين الثانية. تعايش سميث مع فقدان بصره وتيقن أن العقل هو أهم شيء حتى لو فقد جميع حواسه.', 5, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'علاقة جملة (الذين لم يتجاوز أعمارهم العام) بجملة (الأطفال الرضع):', '["تأكيد على مدلولها", "نتيجة", "تخصيص عمومها", "تكرار المعنى"]'::jsonb, 2, 'الرضع لفظ عام، وتحديد من لم يتجاوزوا العام يخصص هذا العموم بفئة أدق.', NULL, 'ad270826-2026-4c00-9d00-270820260001', 'e1a82702-2026-4c00-9d00-000000000002', 'كشفت دراسة حديثة أن الحوادث المرورية تعد السبب الأكبر لوفيات الرضع بالمملكة بنسبة تصل إلى ٤٠٪، موضحة أن ٥٠٪ من الوفيات في حوادث السيارات تحدث لأطفال لم يتجاوز عمرهم العام، وتحدث نتيجة تجاهل استخدام المقاعد المخصصة وأحزمة الأمان؛ حيث وصلت حوادث المرور في السعودية إلى خمسة أضعاف نسبة الحوادث في أمريكا وكندا، وتزيد عن بريطانيا تسعة أضعاف، وذلك بسبب قلة الوعي وعدم الالتزام بالأنظمة والقوانين المرورية مع العاطفة الجامحة تجاه الأطفال إلا أن الموت لا يتناسب معها. وأضافت الدراسة الموسعة التي أجراها كرسي أرامكو للسلامة المرورية بجامعة الإمام عبد الرحمن بن فيصل أن مقاعد الأطفال تخفض نسبة الوفيات عند الرضع بنسبة ٧١٪، كما تقلل الإصابات والاحتياج للعلاج بالمستشفى بنسبة ٦٩٪.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'يفهم من النص أن أقل دولة في حوادث المرور للأطفال:', '["بريطانيا", "كندا", "أمريكا وكندا", "السعودية"]'::jsonb, 0, 'حوادث السعودية خمسة أضعاف أمريكا وكندا وتسعة أضعاف بريطانيا؛ فالأقل نسبةً بريطانيا.', NULL, 'ad270826-2026-4c00-9d00-270820260001', 'e1a82702-2026-4c00-9d00-000000000002', 'كشفت دراسة حديثة أن الحوادث المرورية تعد السبب الأكبر لوفيات الرضع بالمملكة بنسبة تصل إلى ٤٠٪، موضحة أن ٥٠٪ من الوفيات في حوادث السيارات تحدث لأطفال لم يتجاوز عمرهم العام، وتحدث نتيجة تجاهل استخدام المقاعد المخصصة وأحزمة الأمان؛ حيث وصلت حوادث المرور في السعودية إلى خمسة أضعاف نسبة الحوادث في أمريكا وكندا، وتزيد عن بريطانيا تسعة أضعاف، وذلك بسبب قلة الوعي وعدم الالتزام بالأنظمة والقوانين المرورية مع العاطفة الجامحة تجاه الأطفال إلا أن الموت لا يتناسب معها. وأضافت الدراسة الموسعة التي أجراها كرسي أرامكو للسلامة المرورية بجامعة الإمام عبد الرحمن بن فيصل أن مقاعد الأطفال تخفض نسبة الوفيات عند الرضع بنسبة ٧١٪، كما تقلل الإصابات والاحتياج للعلاج بالمستشفى بنسبة ٦٩٪.', 2, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'الضمير في كلمة (معها) يعود على:', '["العاطفة", "السلامة", "الحوادث", "الأطفال"]'::jsonb, 0, 'التقدير: الموت لا يتناسب مع تلك العاطفة الجامحة تجاه الأطفال.', NULL, 'ad270826-2026-4c00-9d00-270820260001', 'e1a82702-2026-4c00-9d00-000000000002', 'كشفت دراسة حديثة أن الحوادث المرورية تعد السبب الأكبر لوفيات الرضع بالمملكة بنسبة تصل إلى ٤٠٪، موضحة أن ٥٠٪ من الوفيات في حوادث السيارات تحدث لأطفال لم يتجاوز عمرهم العام، وتحدث نتيجة تجاهل استخدام المقاعد المخصصة وأحزمة الأمان؛ حيث وصلت حوادث المرور في السعودية إلى خمسة أضعاف نسبة الحوادث في أمريكا وكندا، وتزيد عن بريطانيا تسعة أضعاف، وذلك بسبب قلة الوعي وعدم الالتزام بالأنظمة والقوانين المرورية مع العاطفة الجامحة تجاه الأطفال إلا أن الموت لا يتناسب معها. وأضافت الدراسة الموسعة التي أجراها كرسي أرامكو للسلامة المرورية بجامعة الإمام عبد الرحمن بن فيصل أن مقاعد الأطفال تخفض نسبة الوفيات عند الرضع بنسبة ٧١٪، كما تقلل الإصابات والاحتياج للعلاج بالمستشفى بنسبة ٦٩٪.', 3, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'العنوان المناسب للنص:', '["حزام الأمان", "الحوادث في السعودية", "حوادث وأخطاء", "جفاء المشاعر"]'::jsonb, 1, 'النص يدور حول أرقام الحوادث المرورية في السعودية وأثر مقاعد الأطفال فيها؛ فأقرب العناوين: الحوادث في السعودية.', NULL, 'ad270826-2026-4c00-9d00-270820260001', 'e1a82702-2026-4c00-9d00-000000000002', 'كشفت دراسة حديثة أن الحوادث المرورية تعد السبب الأكبر لوفيات الرضع بالمملكة بنسبة تصل إلى ٤٠٪، موضحة أن ٥٠٪ من الوفيات في حوادث السيارات تحدث لأطفال لم يتجاوز عمرهم العام، وتحدث نتيجة تجاهل استخدام المقاعد المخصصة وأحزمة الأمان؛ حيث وصلت حوادث المرور في السعودية إلى خمسة أضعاف نسبة الحوادث في أمريكا وكندا، وتزيد عن بريطانيا تسعة أضعاف، وذلك بسبب قلة الوعي وعدم الالتزام بالأنظمة والقوانين المرورية مع العاطفة الجامحة تجاه الأطفال إلا أن الموت لا يتناسب معها. وأضافت الدراسة الموسعة التي أجراها كرسي أرامكو للسلامة المرورية بجامعة الإمام عبد الرحمن بن فيصل أن مقاعد الأطفال تخفض نسبة الوفيات عند الرضع بنسبة ٧١٪، كما تقلل الإصابات والاحتياج للعلاج بالمستشفى بنسبة ٦٩٪.', 4, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'أي الآتي خاطئ بالنسبة لما ركزت عليه الهيئة التي تراقب حقوق الموظف؟', '["الحالة الصحية للموظف", "التقيد بوقت العمل", "أوقات رسائل البريد الإلكتروني", "الحرص على متابعة إنجاز الأعمال"]'::jsonb, 3, 'تركيز الهيئة على حماية وقت الموظف وصحته لا على مراقبة إنجازه؛ فمتابعة إنجاز الأعمال ليست مما ركزت عليه.', NULL, 'ad270826-2026-4c00-9d00-270820260001', 'e1a82703-2026-4c00-9d00-000000000003', 'قامت شركة بي إم سي بتشغيل موظفيها عن بعد بسبب قلة المكاتب، ووجدت أن نتائج العمل عن بعد أحسن من الحضوري؛ فقد زادت إنتاجية الموظفين في العمل عن بعد لأن الشخص يصبح مدير نفسه ويشعر بالمسؤولية. وهذا جعل الهيئة التي تراقب حقوق الموظف تغير المديرين وتعلمهم: أوقات رسائل البريد الإلكتروني، وإخبار الموظف بعدم تجاوز وقت العمل، ومنعه من العمل في منتصف الليل وما إلى ذلك، ومراعاة الحالة الصحية للموظف.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'أي مما يلي لم تحققه شركة بي إم سي نتيجة العمل عن بعد؟', '["زيادة الإنتاجية", "التطور", "خفض التكاليف", "تقليل الرواتب"]'::jsonb, 3, 'النص ذكر زيادة الإنتاجية وتحسن النتائج وقلة الحاجة للمكاتب، ولم يذكر أي مساس بالرواتب.', NULL, 'ad270826-2026-4c00-9d00-270820260001', 'e1a82703-2026-4c00-9d00-000000000003', 'قامت شركة بي إم سي بتشغيل موظفيها عن بعد بسبب قلة المكاتب، ووجدت أن نتائج العمل عن بعد أحسن من الحضوري؛ فقد زادت إنتاجية الموظفين في العمل عن بعد لأن الشخص يصبح مدير نفسه ويشعر بالمسؤولية. وهذا جعل الهيئة التي تراقب حقوق الموظف تغير المديرين وتعلمهم: أوقات رسائل البريد الإلكتروني، وإخبار الموظف بعدم تجاوز وقت العمل، ومنعه من العمل في منتصف الليل وما إلى ذلك، ومراعاة الحالة الصحية للموظف.', 2, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'ما الكلمة التي يمكن حذفها من النص دون إخلال بالمعنى؟', '["الناس", "لينير", "طريقهم", "فاعترضهم"]'::jsonb, 2, 'قولنا «لينير للناس» مكتفٍ بمعناه، وحذف «طريقهم» لا يخل بالمقصود.', NULL, 'ad270826-2026-4c00-9d00-270820260001', 'e1a82704-2026-4c00-9d00-000000000004', 'هذا ما صنع المسلمون المجاهدون؛ نزل عليهم المصباح الهادي في حراء والدنيا تتخبط في الظلماء، فحملناه لينير للناس طريقهم، فاعترضهم الآخرون.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'يقصد بـ(الظلماء):', '["الظلام", "الجهل", "الحروب", "البغضاء"]'::jsonb, 1, 'الظلماء هنا رمز لما كانت عليه الدنيا قبل نزول الوحي، وهو ظلام الجهل والضلال.', NULL, 'ad270826-2026-4c00-9d00-270820260001', 'e1a82704-2026-4c00-9d00-000000000004', 'هذا ما صنع المسلمون المجاهدون؛ نزل عليهم المصباح الهادي في حراء والدنيا تتخبط في الظلماء، فحملناه لينير للناس طريقهم، فاعترضهم الآخرون.', 2, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'الضمير في كلمة (فحملناه) يعود على:', '["المصباح", "المسلمين", "حراء", "الظلماء"]'::jsonb, 0, 'المحمول لينير الطريق هو المصباح الهادي المذكور قبلها.', NULL, 'ad270826-2026-4c00-9d00-270820260001', 'e1a82704-2026-4c00-9d00-000000000004', 'هذا ما صنع المسلمون المجاهدون؛ نزل عليهم المصباح الهادي في حراء والدنيا تتخبط في الظلماء، فحملناه لينير للناس طريقهم، فاعترضهم الآخرون.', 3, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'من أولى زوجات النبي صلى الله عليه وسلم؟', '["خديجة", "عائشة", "حفصة", "سودة"]'::jsonb, 0, 'النص صريح: تزوج النبي صلى الله عليه وسلم السيدة خديجة بنت خويلد وهي أولى زوجاته.', NULL, 'ad270826-2026-4c00-9d00-270820260001', 'e1a82705-2026-4c00-9d00-000000000005', '١- كان النبي محمد صلى الله عليه وسلم قبل بعثته النبوية يُعرف في قومه بسمعة طيبة وأخلاق كريمة، فقد لُقب بالصادق الأمين نظرًا لصدق حديثه وأمانته في كل أموره. وكان الناس يتجمعون حوله للاستماع إلى كلامه الحكيم وأخلاقه الفاضلة، حيث كان مثلًا أعلى في الصدق والأمانة والشجاعة والكرم.
٢- بعد أن بلغ النبي صلى الله عليه وسلم الأربعين من عمره جاءه الوحي من الله سبحانه وتعالى في غار حراء، وكان هذا الحدث علامة فارقة في حياة النبي وأمته، حيث بدأ الدعوة إلى الإسلام. واجه النبي صلى الله عليه وسلم في بداية دعوته الكثير من الصعاب والمعارضة من قومه، إلا أنه صبر وثابر في سبيل نشر دعوة الإسلام. وقد تزوج النبي صلى الله عليه وسلم السيدة خديجة بنت خويلد وهي أولى زوجاته، والتي آمنت به ودعمته في دعوته.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'نوع النص:', '["ترجمة", "سيرة", "مقال", "قصة"]'::jsonb, 1, 'النص يعرض حياة النبي صلى الله عليه وسلم قبل البعثة وبعدها عرضًا تاريخيًا متسلسلًا، وهذا هو فن السيرة.', NULL, 'ad270826-2026-4c00-9d00-270820260001', 'e1a82705-2026-4c00-9d00-000000000005', '١- كان النبي محمد صلى الله عليه وسلم قبل بعثته النبوية يُعرف في قومه بسمعة طيبة وأخلاق كريمة، فقد لُقب بالصادق الأمين نظرًا لصدق حديثه وأمانته في كل أموره. وكان الناس يتجمعون حوله للاستماع إلى كلامه الحكيم وأخلاقه الفاضلة، حيث كان مثلًا أعلى في الصدق والأمانة والشجاعة والكرم.
٢- بعد أن بلغ النبي صلى الله عليه وسلم الأربعين من عمره جاءه الوحي من الله سبحانه وتعالى في غار حراء، وكان هذا الحدث علامة فارقة في حياة النبي وأمته، حيث بدأ الدعوة إلى الإسلام. واجه النبي صلى الله عليه وسلم في بداية دعوته الكثير من الصعاب والمعارضة من قومه، إلا أنه صبر وثابر في سبيل نشر دعوة الإسلام. وقد تزوج النبي صلى الله عليه وسلم السيدة خديجة بنت خويلد وهي أولى زوجاته، والتي آمنت به ودعمته في دعوته.', 2, 'active', false);
END IF;
END
